edits:
/* Living city 0.4: a non-modal, explicitly match-credit-only casino. */
.city-life{position:absolute;top:211px;left:31px;display:flex;align-items:center;gap:9px;pointer-events:none;color:#46634d;max-width:245px;font-size:11px;line-height:1.5;background:#faf9f0dd;padding:10px 13px;border:1px solid #e5e7d8;border-radius:12px}
.city-life b,.city-life small{display:block}.city-life small{font-size:9px;color:#697d6d}.final-lap{top:277px}
.casino-entry{display:flex;align-items:center;gap:12px;width:100%;background:#e9eedc;color:#254e42;border:1px solid #d8dfc8;border-radius:15px;padding:13px;text-align:left;cursor:pointer;margin-top:14px;font:inherit}.casino-entry>span:nth-child(2){flex:1}.casino-entry strong,.casino-entry small{display:block}.casino-entry strong{font-size:13px}.casino-entry small{font-size:9px;margin-top:4px;color:#6b7d6b}.casino-chip{border:2px dashed #9cac72;border-radius:50%;height:32px;width:32px;display:grid;place-items:center;font-size:19px;font-weight:700}
.casino-panel{position:fixed;z-index:46;right:18px;top:90px;bottom:25px;width:min(426px,calc(100vw - 32px));box-sizing:border-box;border:1px solid #d7dfd6;border-radius:22px;background:#faf9f3;color:#254e42;padding:23px;overflow:auto;box-shadow:0 18px 60px #173c3a38}.casino-panel[hidden]{display:none}.casino-panel .eyebrow{font-size:8px;letter-spacing:1.2px}.casino-panel .deal-head h2{font-size:25px;margin-top:9px}
.roulette-art{display:flex;align-items:center;justify-content:center;gap:28px;margin:18px 0;background:radial-gradient(ellipse at 20% 30%,#43786d,#1d4239);padding:20px;border-radius:16px;color:#f1e6b9}.roulette-disc{width:112px;height:112px;border:7px solid #dbbd76;border-radius:50%;background:repeating-conic-gradient(#bd7767 0deg 9.7deg,#2c4b42 9.7deg 19.4deg);box-shadow:0 0 0 3px #527765;display:grid;place-items:center;transform:rotate(-20deg)}.roulette-disc span{display:grid;place-items:center;width:64px;height:64px;border-radius:50%;background:#24493f;border:3px solid #d9be7c;font-size:31px}.roulette-caption{font-size:15px;font-weight:700;line-height:1.5;letter-spacing:2px}.roulette-caption small{font-size:10px;letter-spacing:1px;font-weight:400}
.casino-warning{font-size:12px;line-height:1.65}.casino-warning strong{display:block;margin-bottom:5px}#casino-status{font-size:12px;background:#eaf0e7;border-radius:10px;padding:11px;line-height:1.5}#casino-form{display:grid;gap:14px}#casino-form fieldset{border:1px solid #d6dfce;border-radius:12px;padding:13px;display:flex;gap:26px}#casino-form legend{font-size:12px;font-weight:650}#casino-form label{font-size:12px;line-height:1.5}#casino-form fieldset label{display:flex;align-items:center;gap:7px}#casino-form input{accent-color:#386956;flex:none}#casino-form .stake-label{font-weight:650}#casino-stake{display:block;width:100%;background:white;border:1px solid #d5ded5;border-radius:10px;padding:11px;color:#254e42;font:inherit;margin-top:7px}.casino-confirm{display:flex;align-items:flex-start;gap:8px}.casino-odds{font-size:11px;line-height:1.7;color:#617565}.roulette-red{background:#ba7568}.roulette-black{background:#34544c}.roulette-green{background:#689d70}i.roulette-red,i.roulette-black{width:11px;height:11px;display:inline-block;border-radius:50%}.casino-settlement{display:flex;align-items:center;gap:12px;border:1px solid #d5ddc8;border-radius:10px;padding:11px;margin-bottom:14px}.casino-settlement>b{border-radius:50%;color:white;font-size:18px;padding:9px}.casino-settlement strong,.casino-settlement small{display:block}.casino-settlement strong{font-size:13px}.casino-settlement small{font-size:10px;line-height:1.5;margin-top:4px}
@media(max-width:1100px){.city-life{top:189px;left:24px;font-size:10px}.final-lap{top:251px}}
@media(max-width:700px){#casino-entry{grid-column:1/-1}.casino-entry{margin-top:0}.city-life{top:113px;left:18px;padding:6px 9px;max-width:190px;font-size:8px}.city-life small{font-size:7px}.final-lap{top:162px}.casino-panel{top:12px;right:12px;bottom:12px;width:calc(100vw - 24px);padding:18px}.casino-panel .deal-head h2{font-size:23px}.casino-panel .eyebrow{font-size:7px}.roulette-art{gap:20px;padding:15px}}
